    @layer utilities {
      /* 幻灯片容器 */
      .ppt-slide {
        @apply relative w-[1280px] h-[720px] mx-auto box-border overflow-hidden;
      }

      /* 全局防溢出约束 - 应用到所有子元素 */
      .ppt-slide *,
      .ppt-slide *::before,
      .ppt-slide *::after {
        @apply box-border;
        max-width: 100%;
      }

      /* 图片/视频/图表防溢出 */
      .ppt-slide img {
        @apply max-w-full max-h-full;
      }

      .ppt-slide video,
      .ppt-slide svg,
      .ppt-slide .echarts-main,
      .ppt-slide .chart-container,
      .ppt-slide [id*="chart" i] {
        @apply max-w-full max-h-full object-contain;
      }

      /* 图表容器高度防御 */
      .ppt-slide [id*="chart" i],
      .ppt-slide .chart-container,
      .ppt-slide .echarts-main {
        width: 100%;
        height: 100%;
        min-height: 160px;
